import {PRODUCTS} from './model.mjs';
import {localizedPath,t,language,translateTree} from './i18n.mjs';
import {garmentPhoto} from '/apparel-ui.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const studioURL=id=>localizedPath('/satin/design-studio')+'?product='+id;
// Apparel appears in the studio as regular product cards; each opens a representative garment,
// and the garment style can be changed inside the designer (same group and category).
export const APPAREL_CARDS=[['T-Shirts','apparel-men-g500','Black'],['Long Sleeve Shirts','apparel-men-g540','Navy'],['Hoodies','apparel-men-g185','Sport Grey'],['Sweatshirts','apparel-men-g180','Maroon'],['Polos','apparel-men-88181','Royal'],['Tank Tops','apparel-men-g220','Red'],['Women’s T-Shirts','apparel-women-g500l','Heliconia'],['Kids T-Shirts','apparel-youth-g500b','Light Blue'],['Hats & Caps','apparel-hats-c130','Black'],['Totes','apparel-totes-q-tees-q800','Natural']].map(([name,id,colour])=>{const p=PRODUCTS.find(p=>p.id===id);const index=p?Math.max(0,p.garment.colors.indexOf(colour)):0;return p&&{name,id,colour:index,group:p.garment.group,category:p.garment.category};}).filter(Boolean);
export const apparelCardFor=product=>APPAREL_CARDS.find(c=>c.id===product?.id)||APPAREL_CARDS.find(c=>c.group===product?.garment?.group&&c.category===product?.garment?.category)||APPAREL_CARDS.find(c=>c.category===product?.garment?.category);
const GROUPS=['Offset print','Large format','Apparel','Commercial vehicles'];
const chevron='<svg width="14" height="14" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m5 7 5 5 5-5" stroke="currentColor" stroke-width="1.5"/></svg>';
const productImage=p=>p.id.startsWith('vehicle-')?'/studio/mockups/'+(p.id==='vehicle-pickup'?'pickup':p.id==='vehicle-minivan'?'minivan':'van')+'.png':'/satin/img/'+p.photo+'-480.webp';
function entries(group){return group==='Apparel'?APPAREL_CARDS.map(c=>({id:c.id,name:c.name,image:garmentPhoto(c.id,c.colour),apparel:true})):PRODUCTS.filter(p=>p.group===group).map(p=>({id:p.id,name:p.name,image:productImage(p)}));}
function links(group,selected){const card=selected.startsWith('apparel-')?apparelCardFor(PRODUCTS.find(p=>p.id===selected))?.id:selected;return entries(group).map(p=>`<a href="${studioURL(p.id)}" ${p.id===card?'aria-current="page"':''}>${esc(t(p.name))}</a>`).join('');}
export function studioNavigation(selected=''){return `<nav class="studio-navigation" aria-label="${esc(t('Studio product menu'))}"><a class="studio-nav-home" href="${localizedPath('/satin/design-studio')}">${esc(t('All products'))}</a>${GROUPS.map(group=>`<details class="studio-nav-group"><summary>${esc(t(group))}${chevron}</summary><div class="studio-mega"><div class="studio-mega-intro"><span>${esc(t('Design Studio'))}</span><h2>${esc(t(group))}</h2></div><div class="studio-mega-links">${links(group,selected)}</div></div></details>`).join('')}</nav>`;}
export function studioPicker(){return `<div class="print-studio studio-picker">${studioNavigation()}<header class="studio-head"><div><span class="studio-eyebrow">SATIN GRAPHIC DESIGN STUDIO</span><h1>What would you like to design?</h1><p>Select a product to open its design workspace.</p></div></header><ol class="studio-steps"><li class="current"><b>1</b><span>Choose product</span></li><li><b>2</b><span>Create your design</span></li><li><b>3</b><span>Review & save</span></li></ol>${GROUPS.map(g=>`<section class="studio-picker-section"><h2>${esc(t(g))}</h2><div class="studio-picker-grid">${entries(g).map(p=>`<a href="${studioURL(p.id)}" ${p.apparel?'class="studio-apparel-card"':''}><img src="${p.image}" alt="${esc(t(p.name))}" loading="lazy"><h3>${esc(t(p.name))}</h3><span>Open designer</span></a>`).join('')}</div></section>`).join('')}</div>`;}
// Closes menus reliably and always navigates with a full page load, so the editor never keeps the previous product.
export function bindStudioNavigation(root,beforeNavigate){const nav=root.querySelector('.studio-navigation');if(!nav)return ()=>{};const groups=[...nav.querySelectorAll('details')];const close=()=>groups.forEach(g=>g.open=false);const click=e=>{if(!nav.contains(e.target))close();};const key=e=>{if(e.key==='Escape'){const open=groups.find(g=>g.open);close();open?.querySelector('summary').focus();}if(e.key==='ArrowDown'&&e.target.matches('.studio-nav-group>summary')){e.preventDefault();e.target.parentElement.open=true;e.target.parentElement.querySelector('a')?.focus();}};const shown=e=>{if(e.persisted)close();};groups.forEach(g=>g.addEventListener('toggle',()=>{if(g.open)groups.filter(o=>o!==g).forEach(o=>o.open=false);}));nav.addEventListener('keydown',key);document.addEventListener('pointerdown',click);window.addEventListener('pageshow',shown);
 let leaving=false;const go=async e=>{const a=e.target.closest('a');if(!a||e.defaultPrevented||e.button>0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();e.stopPropagation();close();if(leaving)return;leaving=true;try{if(beforeNavigate&&await beforeNavigate(a.href)===false){leaving=false;return;}}catch{}location.assign(a.href);};nav.addEventListener('click',go);
 translateTree(nav);return ()=>{document.removeEventListener('pointerdown',click);window.removeEventListener('pageshow',shown);nav.removeEventListener('keydown',key);nav.removeEventListener('click',go);};}
